    def cast(self, a: Tensor, dtype: Union[str, Any]) -> Tensor:
        if isinstance(dtype, str):
            jax_dtype = getattr(jnp, dtype)
        else:
            jax_dtype = dtype
        a = jnp.asarray(a)
