import jax, jax.numpy as jnp
import optax
import tensorcircuit as tc
tc.set_backend('jax')
backend=tc.backend
n=8
L=2

def make_mvp():
    zz_structs=[[3 if (j==i or j==i+1) else 0 for j in range(n)] for i in range(7)]
    x_structs=[[1 if j==i else 0 for j in range(n)] for i in range(n)]
    return tc.quantum.PauliStringSum2MVP(zz_structs+x_structs, [-1.0]*7+[-1.05]*8)
mvp=make_mvp()

def energy_from_state(st):
    s=backend.reshape(st,[2]*16)
    ds=tc.quantum.reduced_wavefunction(s, subsystem_to_keep=list(range(n)))
    ds=backend.reshape(ds,[-1])
    norm=backend.norm(ds)
    ds=ds/norm
    hp=mvp(ds)
    return backend.real(backend.sum(backend.conj(ds)*hp))

def circuit_state(params, status):
    c=tc.Circuit(16)
    for l in range(2):
        for i in range(n): c.ry(i, theta=params[l,0,i])
        for i in range(n): c.ry(8+i, theta=params[l,1,i])
        for i in range(n): c.rzz(8+i,i, theta=params[l,2,i])
        for j in range(8,15): c.cnot(j,j+1)
        for i in range(n):
            r=c.cond_measurement(8+i, status=status[l,i])
            c.conditional_gate(r, [tc.gates.rzz_gate(theta=params[l,3,i]), tc.gates.rzz_gate(theta=params[l,4,i])], 8+i, i)
        for j in range(7): c.cnot(j,j+1)
        for i in range(n): c.rz(i, theta=params[l,5,i])
    return c.state()

def one_energy(params,status):
    return energy_from_state(circuit_state(params,status))

def objective(params,statuses):
    es=jax.vmap(one_energy,in_axes=(None,0))(params,statuses)
    return jnp.mean(es)

if __name__=='__main__':
    seed=2047
    rng=np.random.default_rng(seed)
    params=np.asarray(rng.normal(0,0.1,size=(2,6,8)),dtype=np.float32)
