    opt=optax.adam(0.02)
    opt_state=opt.init(jparams)
    history=[]
    times=[]
    for step in range(100):
        t=time.time()
        v,g=val_grad(jparams,jnp.asarray(statuses))
        updates,opt_state=opt.update(g,opt_state)
        jparams=optax.apply_updates(jparams,updates)
        history.append(float(v))
        times.append(time.time()-t)
        if step%10==0 or step==99:
            print(step,'v',history[-1],'step time',times[-1])
    print('total',sum(times),'max',max(times),'mean',np.mean(times))
    print('final energies via vmap jit')
    ef=jax.jit(jax.vmap(one_energy,in_axes=(None,0)))
    es=ef(jparams,jnp.asarray(statuses))
    print(es[:5], np.mean(np.asarray(es)))
